    """
    Implements a recursive backtracking algorithm to match a given regex pattern against a text.
    Supports literal characters, '.' (matches any single character), '*' (zero or more of the preceding element),
    and '+' (one or more of the preceding element).
    """

    def is_match(p_index: int, t_index: int) -> bool:
        if p_index == len(pattern) and t_index == len(text):
            return True
        if p_index < len(pattern) and p_index + 1 < len(pattern) and pattern[p_index + 1] == '*':
            return (is_match(p_index + 2, t_index) or 
                    (t_index < len(text) and 
                     (pattern[p_index] == text[t_index] or pattern[p_index] == '.') and 
                     is_match(p_index, t_index + 1)))
        if p_index < len(pattern) and t_index < len(text) and (pattern[p_index] == text[t_index] or pattern[p_index] == '.'):
            return is_match(p_index + 1, t_index + 1)
        if p_index < len(pattern) and p_index + 1 < len(pattern) and pattern[p_index + 1] == '+':
            return (t_index < len(text) and 
                    (pattern[p_index] == text[t_index] or pattern[p_index] == '.') and 
                    (is_match(p_index, t_index + 1) or is_match(p_index + 2, t_index)))
        return False

    return is_match(0, 0)

